document.addEventListener("DOMContentLoaded",()=>{const e=document.getElementById("td-login-form"),t=document.getElementById("td-login-btn"),n=t.querySelector(".td-btn-text"),s=t.querySelector(".td-spinner");e.addEventListener("submit",async a=>{a.preventDefault();const o=e.username.value.trim(),d=e.password.value;if(o&&d){t.disabled=!0,n.style.display="none",s.style.display="block";try{const e=new FormData;e.append("action","auth.login"),e.append("username",o),e.append("password",d);const a=await fetch("/api/index.php",{method:"POST",body:e}),r=await a.json();r.success?(TeleDrive.toast("Authentication successful. Redirecting...","success"),setTimeout(()=>{window.location.href="/"},800)):(TeleDrive.toast(r.error||"Invalid credentials.","error"),t.disabled=!1,n.style.display="block",s.style.display="none")}catch(e){TeleDrive.toast("Network error during authentication.","error"),t.disabled=!1,n.style.display="block",s.style.display="none"}}else TeleDrive.toast("Please enter both username and password.","warning")})});